$parentAlive = [bool](Get-Process -Id $app.Id -ErrorAction SilentlyContinue)
$hold.WaitForExit(5000) | Out-Null
$result = [pscustomobject]@{SourceCommit=$head;Action='terminate only desktop server';ServerPid=$server.Id;ElectronPid=$app.Id;ElectronStillAlive=$parentAlive;PreviewPid=$preview.pid;PreviewDescendantPid=$preview.descendantPid;CodeWorkerPid=$workers[0].ProcessId;SyntheticCliPid=$cli[0].ProcessId;OriginalPythonPid=$creator.pid;AllServerTreeProcessesGone=($remaining.Count -eq 0);ElapsedMilliseconds=[Math]::Round($elapsed,2);Before=$owned;Remaining=$remaining;CreatorHoldExit=if($hold.HasExited){$hold.ExitCode}else{$null}}
[IO.File]::WriteAllText((Join-Path $evidence "$label-server-first.json"),($result | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
$result | ConvertTo-Json -Depth 6
if (-not $parentAlive -or $remaining.Count -ne 0 -or -not $hold.HasExited -or $hold.ExitCode -ne 0) { throw 'Server-first cleanup proof failed or mixed with parent exit' }
} catch {
  $failure = @{SourceCommit=$head;Error=$_.Exception.Message;RemainingBeforeCleanup=@($owned | Where-Object {Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue});ManualCleanupIsNotProof=$true}
  [IO.File]::WriteAllText((Join-Path $evidence "$label-server-first-failure.json"),($failure | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
  throw
} finally {
  $cleanup = @()
  foreach ($item in $owned) {
    $live = Get-Process -Id $item.ProcessId -ErrorAction SilentlyContinue
    if ($live -and [Math]::Abs(($live.StartTime.ToUniversalTime() - $item.CreationDate.ToUniversalTime()).TotalMilliseconds) -lt 100) {
      $cleanup += [int]$item.ProcessId
      & "$env:SystemRoot\System32\taskkill.exe" /PID $item.ProcessId /T /F | Out-Null
    }
  }
  # The independent observer must finish or resume its held child. Never kill it while suspended.
  if ($hold -and -not $hold.HasExited) { $hold.WaitForExit(65000) | Out-Null }
  $liveApp = Get-Process -Id $app.Id -ErrorAction SilentlyContinue
  if ($liveApp -and $liveApp.Path -eq $launch.Executable -and [Math]::Abs(($liveApp.StartTime.ToUniversalTime() - [DateTime]::Parse($launch.StartedAt).ToUniversalTime()).TotalSeconds) -lt 3) {
    $cleanup += $app.Id
    Stop-Process -Id $app.Id -Force
  }
  [IO.File]::WriteAllText((Join-Path $evidence "$label-manual-cleanup.json"),(@{ManualCleanupIsNotProof=$true;SignalledPids=$cleanup;ObserverExited=($null -eq $hold -or $hold.HasExited);Remaining=@($owned | Where-Object {Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue})} | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
}
