if ($launch.SourceCommit -ne $head) { throw 'Wrong package source' }
$app = Get-Process -Id $launch.Pid -ErrorAction Stop
if ($app.Path -ne $launch.Executable -or [Math]::Abs(($app.StartTime.ToUniversalTime() - [DateTime]::Parse($launch.StartedAt).ToUniversalTime()).TotalSeconds) -gt 3) { throw 'App identity changed' }
$appStarted = $app.StartTime.ToUniversalTime()
$package = Split-Path -Parent $launch.Executable
$node = Join-Path $package 'resources\node\node.exe'
$python = Join-Path $package 'resources\original-runtime\python\python.exe'
$bridge = Join-Path $package 'resources\original-runtime\bridge\managed_project_workspace.py'
$cdp = Join-Path $root 'acceptance-fixture\cdp.mjs'
$projectFolder = if ($ReuseRegisteredFixture) { Join-Path $root 'profiles\acceptance\.vivary\workbench\projects\acceptance-positive' } else { Join-Path $root 'preview-tree-fixture' }
$preview = Get-Content -Raw -LiteralPath (Join-Path $projectFolder 'preview-process.json') | ConvertFrom-Json
if ($preview.descendantMode -ne 'attached' -or [DateTime]::Parse($preview.startedAt) -lt [DateTime]::Parse($launch.StartedAt)) { throw 'Need a current non-detached preview descendant' }
$servers = @(Get-CimInstance Win32_Process | Where-Object { $_.ParentProcessId -eq $app.Id -and $_.Name -eq 'node.exe' -and $_.CommandLine -like '*desktop-server.mjs*' })
if ($servers.Count -ne 1) { throw 'Expected one desktop server' }
$server = Get-Process -Id $servers[0].ProcessId -ErrorAction Stop
$serverStarted = $server.StartTime.ToUniversalTime()
if ($server.Path -ne $node) { throw 'Unexpected server executable' }
$owned = @($servers[0] | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
$hold = $null
$modePath = Join-Path $root 'codex-fixture\mode.json'
$originalMode = [IO.File]::ReadAllBytes($modePath)
$appOwned = @([pscustomobject]@{ProcessId=$app.Id;ParentProcessId=0;Name=$app.ProcessName;CreationDate=$appStarted})
function Get-RemainingIdentities($records) {
  @($records | Where-Object {
    $live = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue
    $live -and [Math]::Abs(($live.StartTime.ToUniversalTime() - $_.CreationDate.ToUniversalTime()).TotalMilliseconds) -lt 1
  })
}
try {
[IO.File]::WriteAllText($modePath,'{"mode":"held-turn"}',[Text.UTF8Encoding]::new($false))
$codeAction = if ($ReuseRegisteredFixture) { 'acceptance-fixture\start-held-code-reused.js' } else { 'acceptance-fixture\start-held-code.js' }
$codeOutput = & $node $cdp evaluate (Join-Path $root $codeAction)
if ($LASTEXITCODE -ne 0) { throw 'Held Code turn did not start' }
[IO.File]::WriteAllText((Join-Path $evidence "$label-code.json"),($codeOutput -join "`n"),[Text.UTF8Encoding]::new($false))
$deadline = [DateTime]::UtcNow.AddSeconds(15)
do {
  $processes = @(Get-CimInstance Win32_Process)
  $workers = @($processes | Where-Object { $_.ParentProcessId -eq $server.Id -and $_.CommandLine -like '*vivary-code-worker.mjs*' })
  $cli = @($processes | Where-Object { $_.CommandLine -like '*codex-fixture*codex.js*app-server*' -and $_.CreationDate.ToUniversalTime() -gt [DateTime]::Parse($launch.StartedAt) })
  if ($workers.Count -eq 1 -and $cli.Count -eq 1) { break }
  if ([DateTime]::UtcNow -gt $deadline) { throw 'Actual Code worker and synthetic CLI did not become live' }
  Start-Sleep -Milliseconds 100
} while ($true)
$holdLog = Join-Path $evidence "$label-creator-hold.log"
$holdError = Join-Path $evidence "$label-creator-hold-error.log"
$arguments = @('-NoProfile','-File',('"'+(Join-Path $root 'creator-hold.ps1')+'"'),'-ServerProcessId',[string]$server.Id,'-ServerStartedUtc',$server.StartTime.ToUniversalTime().ToString('o'),'-BundledPythonPath',('"'+$python+'"'),'-BridgePath',('"'+$bridge+'"'),'-FindSeconds','20','-HoldSeconds','60')
$hold = Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList $arguments -WindowStyle Hidden -PassThru -RedirectStandardOutput $holdLog -RedirectStandardError $holdError
$deadline = [DateTime]::UtcNow.AddSeconds(15)
do {
  Start-Sleep -Milliseconds 100
  if ($hold.HasExited -or [DateTime]::UtcNow -gt $deadline) { throw 'Original-command observer did not arm' }
} while (-not (Select-String -LiteralPath $holdLog -SimpleMatch '"event":"armed"' -Quiet))
& $node $cdp evaluate (Join-Path $root 'acceptance-fixture\start-original-catalog.js')
if ($LASTEXITCODE -ne 0) { throw 'Original catalog request did not start' }
$deadline = [DateTime]::UtcNow.AddSeconds(10)
do {
  Start-Sleep -Milliseconds 50
  $line = Select-String -LiteralPath $holdLog -SimpleMatch '"event":"creator-suspended"' | Select-Object -First 1
  if ($line) { break }
  if ($hold.HasExited -or [DateTime]::UtcNow -gt $deadline) { throw 'Actual original Python was not held before its command deadline' }
} while ($true)
$creator = $line.Line | ConvertFrom-Json
$all = @(Get-CimInstance Win32_Process)
$ids = [Collections.Generic.HashSet[int]]::new()
$ids.Add($server.Id) | Out-Null
do {
  $count = $ids.Count
  foreach ($item in $all) { if ($ids.Contains([int]$item.ParentProcessId)) { $ids.Add([int]$item.ProcessId) | Out-Null } }
} while ($ids.Count -ne $count)
$required = @([int]$preview.pid,[int]$preview.descendantPid,[int]$workers[0].ProcessId,[int]$cli[0].ProcessId,[int]$creator.pid)
foreach ($requiredId in $required) { if (-not $ids.Contains($requiredId)) { throw 'A required process is outside the server tree' } }
$owned = @($all | Where-Object { $ids.Contains([int]$_.ProcessId) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
$appOwned = @($all | Where-Object { $_.ProcessId -eq $app.Id -or ($_.ParentProcessId -eq $app.Id -and $_.ProcessId -ne $server.Id) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
$liveServer = Get-Process -Id $server.Id -ErrorAction Stop
if ($liveServer.Path -ne $node -or [Math]::Abs(($liveServer.StartTime.ToUniversalTime() - $serverStarted).TotalMilliseconds) -ge 1) { throw 'Server identity changed before the root-only kill' }
$timer = [Diagnostics.Stopwatch]::StartNew()
# This is root-only termination. No tree operation or Electron kill is used.
Stop-Process -Id $server.Id -Force
do {
  $remaining = @($owned | Where-Object { Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue })
  if ($remaining.Count -eq 0) { break }
  Start-Sleep -Milliseconds 50
} while ($timer.Elapsed.TotalSeconds -lt 5)
$elapsed = $timer.Elapsed.TotalMilliseconds
$parentAlive = [bool](Get-Process -Id $app.Id -ErrorAction SilentlyContinue)
$hold.WaitForExit(5000) | Out-Null
$result = [pscustomobject]@{SourceCommit=$head;Action='terminate only desktop server';ServerPid=$server.Id;ElectronPid=$app.Id;ElectronStillAlive=$parentAlive;PreviewPid=$preview.pid;PreviewDescendantPid=$preview.descendantPid;CodeWorkerPid=$workers[0].ProcessId;SyntheticCliPid=$cli[0].ProcessId;OriginalPythonPid=$creator.pid;AllServerTreeProcessesGone=($remaining.Count -eq 0);ElapsedMilliseconds=[Math]::Round($elapsed,2);Before=$owned;Remaining=$remaining;CreatorHoldExit=if($hold.HasExited){$hold.ExitCode}else{$null}}
[IO.File]::WriteAllText((Join-Path $evidence "$label-server-first.json"),($result | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
$result | ConvertTo-Json -Depth 6
if (-not $parentAlive -or $remaining.Count -ne 0 -or -not $hold.HasExited -or $hold.ExitCode -ne 0) { throw 'Server-first cleanup proof failed or mixed with parent exit' }
} catch {
  $failure = @{SourceCommit=$head;Error=$_.Exception.Message;RemainingBeforeCleanup=@($owned | Where-Object {Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue});ManualCleanupIsNotProof=$true}
  [IO.File]::WriteAllText((Join-Path $evidence "$label-server-first-failure.json"),($failure | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
  throw
} finally {
  $cleanup = @()
  $cleanupCommands = @()
  try {
    foreach ($item in (Get-RemainingIdentities $owned)) {
      $cleanup += [int]$item.ProcessId
      $ErrorActionPreference = 'Continue'
      & "$env:SystemRoot\System32\taskkill.exe" /PID $item.ProcessId /T /F | Out-Null
      $cleanupCommands += @{Pid=[int]$item.ProcessId;ExitCode=$LASTEXITCODE}
      $ErrorActionPreference = 'Stop'
    }
    # A retained observer handle identifies this helper. Never kill it while it may hold Python.
    $observerExited = $null -eq $hold -or $hold.HasExited
    if (-not $observerExited) { $observerExited = $hold.WaitForExit(65000) }
    $liveApp = Get-Process -Id $app.Id -ErrorAction SilentlyContinue
    if ($liveApp -and $liveApp.Path -eq $launch.Executable -and [Math]::Abs(($liveApp.StartTime.ToUniversalTime() - $appStarted).TotalMilliseconds) -lt 1) {
      $cleanup += $app.Id
      Stop-Process -Id $app.Id -Force
      $liveApp.WaitForExit(5000) | Out-Null
    }
    $deadline = [DateTime]::UtcNow.AddSeconds(5)
    do {
      $cleanupRemaining = @(Get-RemainingIdentities (@($owned)+@($appOwned)))
      if ($cleanupRemaining.Count -eq 0) { break }
      Start-Sleep -Milliseconds 100
    } while ([DateTime]::UtcNow -lt $deadline)
    $cleanupResult = @{ManualCleanupIsNotProof=$true;SignalledPids=$cleanup;Commands=$cleanupCommands;ObserverExited=$observerExited;Remaining=$cleanupRemaining}
    [IO.File]::WriteAllText((Join-Path $evidence "$label-manual-cleanup.json"),($cleanupResult | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
    if (-not $observerExited -or $cleanupRemaining.Count -ne 0) { throw 'Owned fixture cleanup did not complete. See the separate cleanup receipt.' }
  } finally {
    [IO.File]::WriteAllBytes($modePath,$originalMode)
  }
}

