export function originalRuntimeTarget(platform, arch) {
  const target = ORIGINAL_RUNTIME_TARGETS[platform + ":" + arch];
  if (!target) throw new Error("The original Vivary runtime does not support " + platform + "/" + arch + ".");
  return target;
}

export async function prepareOriginalRuntime({
  destination,
  platform,
  arch,
  repository,
  sourceCommit,
      - name: maintained workbench checks
        run: pnpm --dir packages/workbench test:maintained

  governed-platform-proof:
    name: governed verification (Windows)
    needs: changes
    runs-on: windows-latest
    timeout-minutes: 15
    steps:
      - uses: actions/checkout@v7.0.1
      - uses: actions/setup-python@v7
        with:
          python-version: "3.11"
      - name: source navigation contract on Windows
        run: python -B scripts/check-source-navigation.py --check
      - name: source navigation contract tests on Windows
        run: python -B scripts/tests/test-source-navigation.py
      - name: install test runner
        run: python -m pip install pytest packaging
      - name: thin init CLI on Windows
        run: python packages/create-vivary/tests/test_init_thin.py
      - name: reviewed workspace creation on Windows
        run: python packages/create-vivary/tests/test_thin_init_preview.py
      - name: managed project bridge on Windows
        run: python packages/workbench/tests/managed-projects-python.test.py
      - uses: actions/setup-node@v7
        with:
          node-version: "22"
      - name: install workbench dependencies
        shell: pwsh
        run: |
          npm install --global pnpm@10.33.2
          if ($LASTEXITCODE -ne 0) { throw "pnpm install failed" }
          pnpm --dir packages/workbench install --frozen-lockfile
          if ($LASTEXITCODE -ne 0) { throw "workbench dependency install failed" }
      - name: desktop and creator shutdown and bytecode cache on Windows
        run: pnpm --dir packages/workbench exec tsx --test tests/desktop-server-shutdown.test.mjs tests/creator-shutdown.test.mjs tests/python-bytecode.test.mjs
      - name: core governed-context contract
        run: python -m pytest packages/core/tests/ -q
      - name: ozone governed-verification facade
        run: python packages/ozone/tests/test_ozone.py
      - name: strato governed-policy consumer
        run: python -m pytest packages/strato/tests/ -q
      - name: installed-wheel capability surface
        shell: pwsh
        run: |
          $smoke = Join-Path $env:RUNNER_TEMP "vivary-wheel-$([guid]::NewGuid())"
          $wheelhouse = Join-Path $smoke "wheels"
          New-Item -ItemType Directory -Path $wheelhouse -Force | Out-Null
          python -m pip wheel --no-deps --wheel-dir $wheelhouse `
            ./packages/core `
"}

